{
  "root_causes": [
    {
      "service": "attractions",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name AS pod, metric, count(*) AS n, min(value) AS mn, max(value) AS mx FROM abnormal_metrics WHERE attr_k8s_pod_name ILIKE 'attractions%' AND metric IN ('k8s.container.ready','k8s.container.restarts') GROUP BY ALL", "claim": "Attractions pod reports container.ready=0 throughout the abnormal window, with restarts rising from 0 to 2–6."},
        {"kind": "metric", "sql": "SELECT 'abn' AS src, attr_k8s_pod_name AS pod, count(*) AS n FROM abnormal_metrics WHERE attr_k8s_pod_name ILIKE 'attractions%' AND metric ILIKE 'container.cpu%' UNION ALL SELECT 'norm', attr_k8s_pod_name, count(*) FROM normal_metrics WHERE attr_k8s_pod_name ILIKE 'attractions%' AND metric ILIKE 'container.cpu%' GROUP BY ALL", "claim": "Attractions container CPU and memory series are absent in the abnormal period but present in normal."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) AS n FROM abnormal_traces WHERE span_name ILIKE 'attractions%' OR service_name = 'attractions' GROUP BY ALL", "claim": "No attractions server spans appear in the abnormal period at all."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE span_name ILIKE 'attractions.Attractions/%' AND service_name='frontend' GROUP BY ALL", "claim": "Frontend's calls to attractions (NearbyCinema, NearbyMus, NearbyRest) almost all end in Error status."}
      ]
    }
  ],
  "propagation": [
    {"from": "attractions", "to": "frontend",
     "evidence": [
       {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants') GROUP BY ALL", "claim": "Frontend HTTP /cinema, /museums and /restaurants return 500 errors on every attempt, matching the failed attractions calls."},
       {"kind": "log", "sql": "SELECT level, count(*) AS n FROM abnormal_logs WHERE service_name='frontend' AND level IN ('ERROR','WARN') AND message ILIKE 'Nearby%failed%' GROUP BY ALL", "claim": "Frontend ERROR logs read 'NearbyX failed for hotelId N', tying user-facing failures to attraction lookups."}
     ]}
  ]
}
